import { describe, expect, it } from "vitest";
import { quote } from "/home/experimenter/experiments/runs/2026-09-17_00-24-43_claim-office-example-mapping_exact-ptdd-v1.1-refactor-subagent-cc_opus-5-no-thinking-3/src/claim-office.js";

// Independent reimplementation of the PRE-refactor formula, byte-for-byte.
function baseline(customer: {yearsWithMHPCO:number}, items: any[], prev = 0): number {
  const P: Record<string, number> = {sword:100, amulet:60, staff:80, potion:40};
  const comp = new Set(["rune","moonstone"]);
  const cs = items.filter(i => comp.has(i.type));
  const mains = items.filter(i => !comp.has(i.type));
  const groups = new Map<string, any[]>();
  for (const c of cs) { const g = groups.get(c.type) ?? []; g.push(c); groups.set(c.type, g); }
  let base = mains.reduce((t,i)=>t+P[i.type],0);
  for (const g of groups.values()) base += g.length === 3 ? 60 : g.length * 25;
  let risk = 0;
  for (const i of items) {
    const ib = comp.has(i.type) ? 25 : P[i.type];
    let r = 0;
    if (i.cursed === true) r += 0.5;
    if ((i.enchantment ?? 0) >= 5) r += 0.3;
    risk += ib * r;
  }
  const first = base * 0.1;
  const loy = customer.yearsWithMHPCO >= 2 ? base * 0.2 : 0;
  const fup = prev > 0 ? base * 0.15 : 0;
  return base + risk + (first - loy - fup) + 5;
}

describe("refactor equivalence", () => {
  it("matches the pre-refactor formula bit-for-bit across a wide grid", () => {
    const types = ["sword","amulet","staff","potion","rune","moonstone"];
    let checked = 0;
    for (const years of [0,1,2,3,7]) {
      for (const prev of [0,1,2]) {
        for (const t1 of types) for (const t2 of types) {
          for (const cursed of [false,true]) for (const ench of [0,4,5,9]) {
            const items = [
              {type:t1, cursed, enchantment:ench},
              {type:t2},
              {type:t2},
            ];
            expect(quote({yearsWithMHPCO:years}, items, prev))
              .toBe(baseline({yearsWithMHPCO:years}, items, prev));
            checked++;
          }
        }
      }
    }
    expect(quote({yearsWithMHPCO:0}, [])).toBe(baseline({yearsWithMHPCO:0}, []));
    console.log("equivalence cases checked:", checked);
  });
});
EOF
